-- Cola na Mãe | schema e políticas de acesso - executar no SQL Editor do Supabase
create extension if not exists pgcrypto;
create table public.households(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 80),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.care_profiles(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,name text not null,kind text not null check(kind in ('child','adult','pet')),birth_date date,notes text,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.household_members(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,user_id uuid not null references auth.users(id),display_name text not null,role text not null default 'caregiver' check(role in ('admin','caregiver')),scope text not null default 'household' check(scope in ('household','profile')),care_profile_id uuid references public.care_profiles(id) on delete cascade,color text not null default '#B7D9FE',created_at timestamptz not null default now(),unique(household_id,user_id),check((scope='household' and care_profile_id is null) or(scope='profile' and care_profile_id is not null)),check(role<>'admin' or scope='household'));
create index members_user_idx on public.household_members(user_id);
create table public.tasks(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,title text not null check(length(title) between 1 and 160),details text,due_at timestamptz,status text not null default 'open' check(status in ('open','done')),assigned_to uuid references auth.users(id),care_profile_id uuid references public.care_profiles(id) on delete set null,planned_by uuid not null references auth.users(id),completed_by uuid references auth.users(id),completed_at timestamptz,created_at timestamptz not null default now());
create table public.family_events(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,title text not null,starts_at timestamptz not null,ends_at timestamptz,place text,assigned_to uuid references auth.users(id),care_profile_id uuid references public.care_profiles(id) on delete set null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.wellbeing_checkins(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,user_id uuid not null references auth.users(id),day date not null,mood text check(mood in ('leve','ok','cansada','no_limite')),water integer not null default 0 check(water between 0 and 50),movement integer not null default 0 check(movement between 0 and 1440),sleep_minutes integer check(sleep_minutes between 0 and 1440),created_at timestamptz not null default now(),unique(user_id,household_id,day));
create table public.meals(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,day date not null,title text not null,cook_id uuid references auth.users(id),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.shopping_items(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,title text not null,checked boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.dreams(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,title text not null,category text not null default 'Da família',target_amount numeric(12,2) not null default 0 check(target_amount>=0),saved_amount numeric(12,2) not null default 0 check(saved_amount>=0),care_profile_id uuid references public.care_profiles(id) on delete set null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.transactions(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,title text not null,amount numeric(12,2) not null check(amount>0),kind text not null check(kind in ('income','expense')),category text not null,due_date date,paid boolean not null default false,assigned_to uuid references auth.users(id),care_profile_id uuid references public.care_profiles(id) on delete set null,created_by uuid not null references auth.users(id),visibility text not null default 'private' check(visibility in ('private','shared')),created_at timestamptz not null default now());
create table public.chat_messages(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,user_id uuid not null references auth.users(id),sender text not null check(sender in ('user','assistant')),content text not null,metadata jsonb,created_at timestamptz not null default now());
create table public.invitations(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,email text not null,role text not null default 'caregiver',scope text not null check(scope in ('household','profile')),care_profile_id uuid references public.care_profiles(id) on delete cascade,token uuid not null unique default gen_random_uuid(),expires_at timestamptz not null default now()+interval '7 days',accepted_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.audit_log(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,actor_id uuid references auth.users(id),event text not null,entity text not null,entity_id uuid,created_at timestamptz not null default now());
-- SECURITY DEFINER evita recursão das políticas de membros. Search path fixo.
create function public.access_level(h uuid,p uuid default null) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.household_members m where m.household_id=h and m.user_id=(select auth.uid()) and (m.scope='household' or (p is not null and m.care_profile_id=p)))$$;
create function public.is_member(h uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.household_members m where m.household_id=h and m.user_id=(select auth.uid()))$$;
revoke all on function public.is_member(uuid) from public;grant execute on function public.is_member(uuid) to authenticated;
create function public.is_admin(h uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.household_members m where m.household_id=h and m.user_id=(select auth.uid()) and m.role='admin')$$;
revoke all on function public.access_level(uuid,uuid) from public;grant execute on function public.access_level(uuid,uuid) to authenticated;
revoke all on function public.is_admin(uuid) from public;grant execute on function public.is_admin(uuid) to authenticated;
-- Função transacional de criação (não permite que cliente se torne admin em casa alheia)
create function public.create_household(p_name text) returns uuid language plpgsql security definer set search_path='' as $$declare hid uuid;uid uuid;begin uid:=auth.uid();if uid is null then raise exception 'Autenticação obrigatória';end if;if length(trim(p_name))<1 or length(p_name)>80 then raise exception 'Nome inválido';end if;insert into public.households(name,created_by) values(trim(p_name),uid) returning id into hid;insert into public.household_members(household_id,user_id,display_name,role,scope,color) values(hid,uid,coalesce(nullif(split_part((select email from auth.users where id=uid),'@',1),''),'Responsável'),'admin','household','#FEB7B7');return hid;end$$;
revoke all on function public.create_household(text) from public;grant execute on function public.create_household(text) to authenticated;
create function public.create_invitation(p_household_id uuid,p_email text,p_scope text,p_profile_id uuid) returns text language plpgsql security definer set search_path='' as $$declare v_token uuid;begin if not public.is_admin(p_household_id) then raise exception 'Somente responsáveis da casa convidam';end if;if p_scope not in ('household','profile') or(p_scope='profile' and (p_profile_id is null or not exists(select 1 from public.care_profiles where id=p_profile_id and household_id=p_household_id))) or(p_scope='household' and p_profile_id is not null) then raise exception 'Escopo inválido';end if;if p_email is null or position('@' in p_email)=0 then raise exception 'E-mail inválido';end if;insert into public.invitations(household_id,email,scope,care_profile_id,created_by) values(p_household_id,lower(trim(p_email)),p_scope,p_profile_id,auth.uid()) returning token into v_token;return v_token::text;end$$;
revoke all on function public.create_invitation(uuid,text,text,uuid) from public;grant execute on function public.create_invitation(uuid,text,text,uuid) to authenticated;
create function public.accept_invitation(p_token text) returns uuid language plpgsql security definer set search_path='' as $$declare inv public.invitations%rowtype;uid uuid;user_email text;begin uid:=auth.uid();if uid is null then raise exception 'Entre na sua conta antes';end if;select lower(email) into user_email from auth.users where id=uid and email_confirmed_at is not null;if user_email is null then raise exception 'Confirme seu e-mail para aceitar convites';end if;select * into inv from public.invitations where token=p_token::uuid for update;if not found or inv.accepted_at is not null or inv.expires_at<now() or inv.email<>user_email then raise exception 'Convite inválido, vencido ou de outro e-mail';end if;insert into public.household_members(household_id,user_id,display_name,role,scope,care_profile_id) values(inv.household_id,uid,split_part(user_email,'@',1),'caregiver',inv.scope,inv.care_profile_id) on conflict(household_id,user_id) do nothing;update public.invitations set accepted_at=now() where id=inv.id;return inv.household_id;end$$;
revoke all on function public.accept_invitation(text) from public;grant execute on function public.accept_invitation(text) to authenticated;
-- RLS: acesso baseado em casa / pessoa cuidada; checkins e conversas estritamente pessoais
alter table public.households enable row level security;alter table public.household_members enable row level security;alter table public.care_profiles enable row level security;alter table public.tasks enable row level security;alter table public.family_events enable row level security;alter table public.wellbeing_checkins enable row level security;alter table public.meals enable row level security;alter table public.shopping_items enable row level security;alter table public.dreams enable row level security;alter table public.transactions enable row level security;alter table public.chat_messages enable row level security;alter table public.invitations enable row level security;alter table public.audit_log enable row level security;
create policy household_select on public.households for select to authenticated using(public.is_member(id));
create policy members_select on public.household_members for select to authenticated using(public.is_member(household_id));
create policy profiles_select on public.care_profiles for select to authenticated using(public.access_level(household_id,id));
create policy profiles_insert on public.care_profiles for insert to authenticated with check(public.is_admin(household_id) and created_by=auth.uid());
create policy profiles_update on public.care_profiles for update to authenticated using(public.is_admin(household_id)) with check(public.is_admin(household_id));
create policy profiles_delete on public.care_profiles for delete to authenticated using(public.is_admin(household_id));
create policy tasks_select on public.tasks for select to authenticated using(public.access_level(household_id,care_profile_id));
create policy tasks_insert on public.tasks for insert to authenticated with check(public.access_level(household_id,care_profile_id) and planned_by=auth.uid() and (assigned_to is null or exists(select 1 from public.household_members where household_id=tasks.household_id and user_id=assigned_to)));
create policy tasks_update on public.tasks for update to authenticated using(public.access_level(household_id,care_profile_id)) with check(public.access_level(household_id,care_profile_id) and (assigned_to is null or exists(select 1 from public.household_members where household_id=tasks.household_id and user_id=assigned_to)));
create policy tasks_delete on public.tasks for delete to authenticated using(public.access_level(household_id,care_profile_id));
create policy events_select on public.family_events for select to authenticated using(public.access_level(household_id,care_profile_id));
create policy events_insert on public.family_events for insert to authenticated with check(public.access_level(household_id,care_profile_id) and created_by=auth.uid());
create policy events_update on public.family_events for update to authenticated using(public.access_level(household_id,care_profile_id)) with check(public.access_level(household_id,care_profile_id));
create policy events_delete on public.family_events for delete to authenticated using(public.access_level(household_id,care_profile_id));
create policy checkin_select on public.wellbeing_checkins for select to authenticated using(user_id=auth.uid());
create policy checkin_insert on public.wellbeing_checkins for insert to authenticated with check(user_id=auth.uid() and public.is_member(household_id));
create policy checkin_update on public.wellbeing_checkins for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and public.is_member(household_id));
create policy meal_select on public.meals for select to authenticated using(public.access_level(household_id));
create policy meal_insert on public.meals for insert to authenticated with check(public.access_level(household_id) and created_by=auth.uid());
create policy meal_update on public.meals for update to authenticated using(public.access_level(household_id)) with check(public.access_level(household_id));
create policy meal_delete on public.meals for delete to authenticated using(public.access_level(household_id));
create policy shopping_select on public.shopping_items for select to authenticated using(public.access_level(household_id));
create policy shopping_insert on public.shopping_items for insert to authenticated with check(public.access_level(household_id) and created_by=auth.uid());
create policy shopping_update on public.shopping_items for update to authenticated using(public.access_level(household_id)) with check(public.access_level(household_id));
create policy shopping_delete on public.shopping_items for delete to authenticated using(public.access_level(household_id));
create policy dream_select on public.dreams for select to authenticated using(public.access_level(household_id,care_profile_id) and(category<>'Só meu' or created_by=auth.uid()));
create policy dream_insert on public.dreams for insert to authenticated with check(public.access_level(household_id,care_profile_id) and created_by=auth.uid());
create policy dream_update on public.dreams for update to authenticated using(public.access_level(household_id,care_profile_id) and(category<>'Só meu' or created_by=auth.uid())) with check(public.access_level(household_id,care_profile_id) and(category<>'Só meu' or created_by=auth.uid()));
create policy dream_delete on public.dreams for delete to authenticated using(public.access_level(household_id,care_profile_id) and(category<>'Só meu' or created_by=auth.uid()));
create policy trx_select on public.transactions for select to authenticated using((visibility='private' and created_by=auth.uid()) or (visibility='shared' and public.access_level(household_id,care_profile_id)));
create policy trx_insert on public.transactions for insert to authenticated with check(created_by=auth.uid() and public.access_level(household_id,care_profile_id));
create policy trx_update on public.transactions for update to authenticated using(created_by=auth.uid()) with check(created_by=auth.uid() and public.access_level(household_id,care_profile_id));
create policy trx_delete on public.transactions for delete to authenticated using(created_by=auth.uid());
create policy chat_select on public.chat_messages for select to authenticated using(user_id=auth.uid());
create policy chat_insert on public.chat_messages for insert to authenticated with check(user_id=auth.uid() and public.is_member(household_id));
create policy invite_select on public.invitations for select to authenticated using(public.is_admin(household_id));
create policy audit_select on public.audit_log for select to authenticated using(public.is_admin(household_id));
-- Log server-side de mutações (não confiar no frontend)
create function public.audit_change() returns trigger language plpgsql security definer set search_path='' as $$declare row_data jsonb;hid uuid;begin row_data:=to_jsonb(coalesce(new,old));hid:=(row_data->>'household_id')::uuid;insert into public.audit_log(household_id,actor_id,event,entity,entity_id) values(hid,auth.uid(),tg_op,tg_table_name,(row_data->>'id')::uuid);return coalesce(new,old);end$$;
create trigger audit_tasks after insert or update or delete on public.tasks for each row execute function public.audit_change();
create trigger audit_transactions after insert or update or delete on public.transactions for each row execute function public.audit_change();
create trigger audit_events after insert or update or delete on public.family_events for each row execute function public.audit_change();
create index tasks_household_due_idx on public.tasks(household_id,due_at);create index events_household_start_idx on public.family_events(household_id,starts_at);create index transactions_household_idx on public.transactions(household_id,created_at desc);
